class IncorrectScpiCommand(Exception):
    """ SCPI command is invalid """


class ScpiConnectionError(Exception):
    """ SCPI connection can't be opened """


class ScpiCommandSendingError(Exception):
    """ SCPI command can't be send """


class ScpiOutputReadingError(Exception):
    """ SCPI query's output can't be read """
